#include <vector>
#include <algorithm>
#include <numeric>

int shortest_span(const std::vector<int>& values, long long threshold) {
    int n = values.size();
    std::vector<long long> prefix_sum(n + 1);
    std::partial_sum(values.begin(), values.end(), prefix_sum.begin() + 1);

    int min_span = n + 1;
    for (int start = 0; start < n; ++start) {
        for (int end = start; end < n; ++end) {
            long long sum = prefix_sum[end + 1] - prefix_sum[start];
            if (sum >= threshold && end - start + 1 < min_span) {
                min_span = end - start + 1;
            }
        }
    }
    return min_span == n + 1 ? 0 : min_span;
}
