#include <vector>
#include <string>
#include <algorithm>
#include <unordered_map>
#include <cassert>

std::vector<std::string> top_words(const std::vector<std::string>& words, int k) {
    if (k <= 0) return {};

    std::unordered_map<std::string, int> word_counts;
    for (const auto& word : words) {
        ++word_counts[word];
    }

    std::vector<std::pair<std::string, int>> sorted_words(word_counts.begin(), word_counts.end());
    std::sort(sorted_words.begin(), sorted_words.end(), [](const auto& a, const auto& b) {
        return a.second == b.second ? a.first < b.first : a.second > b.second;
    });

    std::vector<std::string> top_k_words;
    for (int i = 0; i < std::min(k, sorted_words.size()); ++i) {
        top_k_words.push_back(sorted_words[i].first);
    }

    return top_k_words;
}

// Test cases
void test_top_words() {
    assert(top_words({}, 3) == {});
    assert(top_words({"apple", "banana", "apple", "orange", "banana"}, 2) == {"banana", "apple"});
    assert(top_words({"hello", "world", "hello", "cpp"}, 1) == {"hello"});
    assert(top_words({"cpp", "is", "fun", "cpp"}, 3) == {"cpp", "fun", "is"});
    assert(top_words({"fun", "is", "cpp", "fun"}, 2) == {"fun", "cpp"});
    assert(top_words({"fun", "is", "cpp", "fun"}, 0) == {});
    assert(top_words({"fun", "is", "cpp", "fun"}, -1) == {});
}

int main() {
    test_top_words();
    return 0;
}
